64	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
65	     * input (e.g. a value without an '@') is rejected.
66	     */
67	    private static final Pattern EMAIL_PATTERN =
68	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
